"""Offline beginner curriculum. Stable IDs preserve learning progress across updates."""
from dataclasses import dataclass


@dataclass(frozen=True)
class Lesson:
    id: str
    module: str
    title: str
    minutes: int
    paragraphs: tuple[str, ...]
    practice: str
    question: str
    answers: tuple[str, str, str]
    correct: int
    explanation: str
    tones: tuple[int, ...] = ()


LESSONS = (
    Lesson('sound', '01 · Музыкальная теория', 'Высота, громкость и тембр', 4, (
        'Высота отвечает на вопрос «низко или высоко звучит голос». Она связана с частотой колебаний: при удвоении частоты мы слышим ту же ноту на октаву выше. Например, ля 440 Гц и ля 880 Гц находятся в разных октавах.',
        'Громкость — отдельное свойство. Можно спеть высокую ноту тихо, а низкую — громко. Повышать голос по высоте не значит кричать.',
        'Тембр — окраска звука. Одна нота у разных людей звучит по-разному. В тренажёре линия показывает прежде всего высоту, а не красоту тембра или правильность техники.'),
        'Произнеси «м-м?» с лёгкой вопросительной интонацией, затем спокойно «м-м». Заметь изменение высоты. Не пытайся сделать звук громче. Аудиопример — две ноты ля в разных октавах; повторять высокую не обязательно.',
        'Что меняется при переходе от 440 Гц к 880 Гц?', ('Голос обязательно становится громче', 'Высота поднимается на октаву', 'Меняется только тембр'), 1,
        'Частота удвоилась: высота поднялась на октаву. Громкость при этом может остаться прежней.', (69, 81)),
    Lesson('notes', '01 · Музыкальная теория', 'Ноты и клавиатура', 5, (
        'Семь основных названий: до, ре, ми, фа, соль, ля, си. В международной буквенной записи это C, D, E, F, G, A, B. В некоторых немецких источниках си обозначается H; приложение использует B.',
        'На клавиатуре чёрные клавиши идут группами по две и по три. До — белая клавиша непосредственно слева от группы из двух чёрных. После си снова идёт до, но уже выше.',
        'На нотном стане пять линий, ноты размещаются и на линиях, и между ними. Ключ определяет их высоту: скрипичный ключ отмечает соль первой октавы на второй линии снизу. Здесь пиано-ролл показывает ту же высоту вертикальным положением: выше на экране — выше звук.'),
        'Прослушай до–ре–ми–фа–соль–ля–си–до. Назови ноты сначала вперёд, затем назад. Найди C и A на таймлайне распевки.',
        'Какой буквой в приложении обозначается ля?', ('A', 'C', 'B'), 0,
        'Ля — A, до — C, си — B.', (60, 62, 64, 65, 67, 69, 71, 72)),
    Lesson('semitones', '01 · Музыкальная теория', 'Полутон, тон, диез и бемоль', 5, (
        'Полутон — расстояние между соседними клавишами фортепиано, включая чёрные. Два полутона составляют целый тон. Между ми и фа, а также си и до — полутон, хотя обе клавиши белые.',
        'Диез ♯ повышает ноту на полутон, бемоль ♭ понижает на полутон. На равномерно темперированной клавиатуре до-диез и ре-бемоль звучат одинаково, но в нотах их запись зависит от музыкального контекста.',
        'В приложении чёрные клавиши подписаны через диез. Число рядом с нотой обозначает октаву, например C4 и C♯4. Это не номер пальца и не длительность.'),
        'Сравни пример: до–до-диез — полутон; до–ре — тон. Сначала послушай, потом попробуй тихо повторить в удобной октаве.',
        'Какое расстояние между ми и фа?', ('Целый тон', 'Два тона', 'Полутон'), 2,
        'Ми и фа — соседние клавиши без чёрной между ними: один полутон.', (60, 61, 60, 62)),
    Lesson('octaves', '01 · Музыкальная теория', 'Октавы и удобная высота', 4, (
        'Октава содержит 12 полутонов. Её крайние звуки имеют одно имя: например, C3 и C4. В научной системе, используемой здесь, C4 — среднее до; в русской традиции это до первой октавы.',
        'Диапазон — все высоты, которые ты можешь издать, а тесситура — область, в которой комфортно петь фразу за фразой. Крайняя доступная нота не обязательно подходит для песни.',
        'Перенос мелодии на октаву сохраняет имена нот. Транспонирование на другое расстояние меняет их. Режим «Любая октава» меняет оценку попадания, но не высоту звучащего минуса.'),
        'Включи «Любая октава» и найди комфортный вариант распевки. Если даже он требует усилия, остановись и выбери другую песню; не проверяй максимальный диапазон.',
        'Что делает режим «Любая октава»?', ('Автоматически транспонирует минус', 'Разрешает другую октаву при оценке', 'Увеличивает громкость микрофона'), 1,
        'Он допускает октавное отличие в оценке. Сам минус остаётся на исходной высоте.', (60, 72)),
    Lesson('rhythm', '01 · Музыкальная теория', 'Пульс, темп и длительности', 6, (
        'Пульс — равномерные доли, под которые удобно считать или шагать. Темп часто задают в BPM: при 60 BPM проходит одна доля в секунду, при 120 — две.',
        'В размере 4/4 в такте четыре четвертные доли. Считай «раз, два, три, четыре» и повторяй. В 3/4 — три четвертные доли. Верхнее число показывает число долей, нижнее — записанную единицу счёта.',
        'Целая длится как две половинные или четыре четвертные; четвертная — как две восьмые. Если четверть равна одной доле, половинная занимает две доли, а восьмая — половину. Паузы тоже имеют длительность: молчание является частью музыки.'),
        'Отстучи ровные четверти на счёт 1–2–3–4. Затем произноси «та» только на 1 и 3, оставляя паузы на 2 и 4. Сохраняй внутренний счёт, даже когда молчишь.',
        'Сколько четвертных долей занимает половинная нота?', ('Одну', 'Две', 'Четыре'), 1,
        'Половинная по длительности равна двум четвертным. Это отношение не зависит от темпа.'),
    Lesson('intervals', '01 · Музыкальная теория', 'Интервалы и направление мелодии', 5, (
        'Интервал — расстояние по высоте между двумя звуками. До–ре — большая секунда (2 полутона), до–ми — большая терция (4), до–соль — чистая квинта (7), до–до выше — октава (12).',
        'Интервалы можно слышать последовательно, как шаг мелодии, или одновременно, как созвучие. Начни с различения направления: следующий звук выше, ниже или такой же.',
        'Мелодия движется поступенно, повторяет звуки или делает скачки. Перед сложным скачком полезно сначала представить следующий звук внутренним слухом, затем спеть. Не компенсируй промах громкостью.'),
        'Послушай до–ми, до–соль, до–до выше. Назови направление и сравни размер скачков. Повторяй только удобные высоты или просто слушай.',
        'Сколько полутонов в чистой квинте?', ('Четыре', 'Семь', 'Двенадцать'), 1,
        'Квинта до–соль содержит семь полутонов.', (60, 64, 60, 67, 60, 72)),
    Lesson('keys', '01 · Музыкальная теория', 'Гамма, тональность и аккорды', 6, (
        'Гамма — упорядоченные звуки лада. Формула мажорной гаммы в тонах и полутонах: тон–тон–полутон–тон–тон–тон–полутон. До мажор получается на белых клавишах от до до до.',
        'Тоника — устойчивый центр, к которому музыка часто стремится вернуться. Тональность связывает этот центр и лад: например, до мажор или ля минор. Натуральный ля минор использует белые клавиши от ля до ля. «Мажор весёлый, минор грустный» — только грубая ассоциация, а не правило настроения.',
        'Аккорд — сочетание нескольких звуков. До-мажорное трезвучие: до–ми–соль, ля-минорное: ля–до–ми. Голос не обязан всегда петь только звуки аккорда: в мелодии бывают проходящие звуки и напряжения, которые затем разрешаются.'),
        'Послушай звуки до-мажорного трезвучия по очереди. Затем пропой короткое до–ре–ми–ре–до и почувствуй возвращение к началу, если эта высота удобна.',
        'Какие ноты образуют до-мажорное трезвучие?', ('До–ре–ми', 'До–ми–соль', 'До–фа–ля'), 1,
        'До, ми и соль — основной тон, большая терция и чистая квинта.', (60, 64, 67, 64, 60)),
    Lesson('voice', '02 · Основы вокала', 'Как возникает голос', 5, (
        'Воздух из лёгких участвует в колебании голосовых складок в гортани. Звук затем изменяется в голосовом тракте — полостях глотки и рта. Язык, губы и мягкое нёбо влияют на гласные и окраску.',
        'Для начала достаточно устойчиво стоять или сидеть, свободно держать шею и не поднимать подбородок вслед за высокой нотой. Плечи не нужно насильно опускать, живот — втягивать до напряжения.',
        'Ощущения вибрации в лице или груди могут помогать ориентироваться, но звук не нужно буквально «посылать» в эти места. Линия высоты в приложении не измеряет напряжение складок и не заменяет обратную связь преподавателя.'),
        'Скажи спокойное «угу», затем слегка протяни последний звук на удобной разговорной высоте. Оставь челюсть и шею свободными. Два-три раза достаточно.',
        'Что стоит делать, когда нота становится выше?', ('Поднимать подбородок', 'Сильно сжимать шею', 'Сохранять свободное положение головы'), 2,
        'Высота не требует подъёма подбородка. Излишнее мышечное усилие обычно мешает.'),
    Lesson('breath', '02 · Основы вокала', 'Дыхание и опора', 6, (
        'Опора — удобное название для согласованной работы дыхания и голосообразования. Задача — управлять выдохом и звуком на протяжении фразы, а не набрать максимум воздуха и вытолкнуть его животом.',
        'Вдохни спокойно, без шумного всасывания и подъёма плеч. Нижние рёбра и живот могут мягко расширяться. При пении не требуется намертво фиксировать корпус или резко напрягать пресс: усилие меняется с фразой.',
        'Диафрагма участвует во вдохе, но команду «пой диафрагмой» не следует понимать как прямое управление отдельной мышцей. Ориентиры — ровный комфортный звук и отсутствие лишнего давления в горле.'),
        'После обычного вдоха спокойно выдыхай на «с» 4–6 секунд, затем отдохни и дыши как обычно. Повтори 2–3 раза. После этого мягко протяни «в» 2–3 секунды. Не выдыхай до предела и не задерживай дыхание. При головокружении прекрати упражнение.',
        'Что лучше описывает опору?', ('Максимальное напряжение пресса', 'Согласованный выдох и голос без лишнего давления', 'Удержание дыхания как можно дольше'), 1,
        'Опора — координация, а не силовое удержание. Комфорт и управляемость важнее длительности выдоха.'),
    Lesson('warmup', '02 · Основы вокала', 'Мягкая разминка', 5, (
        'Начинай с привычного среднего участка голоса и небольшой громкости. Разминка нужна, чтобы постепенно настроить координацию; она не обязана расширять диапазон или утомлять.',
        'Подходят спокойное «м», «в», лёгкая трель губ, если она получается без усилия. Можно плавно менять высоту на небольшом расстоянии. Не нужно зажимать губы или давить воздухом ради трели.',
        'В первые занятия достаточно нескольких минут: немного обычной речи, короткие мягкие звуки, затем простая мелодия. После упражнения голос должен оставаться удобным. Длинная разминка через усталость не делает тренировку полезнее.'),
        'Сделай три коротких мягких «м-м-м» с паузами. Затем два небольших скольжения вверх-вниз на «в». Заверши знакомой короткой фразой. Если трель или гудение неприятны, пропусти их.',
        'С чего лучше начинать распевку?', ('С самой высокой ноты', 'С удобной середины и небольшой громкости', 'С максимально долгого громкого звука'), 1,
        'Спокойное начало в удобной тесситуре помогает постепенно включить голос.'),
    Lesson('intonation', '02 · Основы вокала', 'Как попадать в ноты', 6, (
        'Интонация — точность высоты в музыкальном контексте. Сначала внимательно послушай эталон, представь его про себя и только затем начни звук. При промахе остановись и повтори, не тяни голос вверх силой.',
        'В тренажёре фиолетовый блок — цель, линия — измеренный голос. Если линия выше цели, нужно ниже; если ниже — выше. Небольшие колебания естественны. Вибрато не обязательно делать специально.',
        'Используй наушники, иначе микрофон может слышать минус вместо тебя. Если линия постоянно смещена по времени, настрой задержку. Проверяй и слухом: ошибки разделения дорожек и бэк-вокал могут искажать эталон.'),
        'Включи учебную распевку, выбери удобную октаву и повтори первые две ноты на «у» или «м». После каждого повторения делай паузу. Сначала добейся спокойного начала ноты, затем ровного продолжения.',
        'Твоя линия выше эталона. Что попробовать?', ('Петь ниже по высоте', 'Петь громче', 'Напрячь горло'), 0,
        'Нужно немного снизить высоту. Изменение громкости само по себе промах не исправляет.'),
    Lesson('registers', '02 · Основы вокала', 'Регистры и переходы', 6, (
        'Голос может звучать плотнее или легче при разных способах работы складок. В обучении встречаются названия «грудной», «головной», «фальцет», «микст»; у разных школ их значения частично различаются.',
        'На переходах между участками диапазона звук может становиться тоньше или менять окраску. Это не повод тянуть привычный плотный звук вверх любой ценой. Полезно уменьшить громкость и исследовать лёгкий удобный вариант.',
        '«Микст» не является кнопкой или одной точкой в лице. Координацию переходов обычно развивают постепенно, с индивидуальной обратной связью. Предельные высоты, форсирование и хриповые эффекты не входят в этот начальный курс.'),
        'На тихом «у» сделай небольшое плавное скольжение в пределах комфортной середины. Не стремись пересечь весь диапазон. Если звук срывается, уменьши расстояние или вернись к речи.',
        'Что делать, если высокая нота требует давления?', ('Сильнее толкать воздух', 'Снизить нагрузку и выбрать удобную высоту', 'Повторять до усталости'), 1,
        'Снизь громкость или высоту. Освоение верхнего диапазона не должно идти через давление и боль.'),
    Lesson('phrases', '02 · Основы вокала', 'Дикция и музыкальная фраза', 5, (
        'Гласные несут большую часть протяжённого звука, согласные помогают понять слова. Чёткая дикция не требует широко растягивать рот или жёстко прижимать язык.',
        'Сначала проговори текст в ритме, затем спой его. Отметь смысловые ударения и места вдоха. Обычно удобно вдыхать на границах фраз, сохраняя смысл предложения.',
        'Динамика — изменения громкости. Лёгкое усиление и ослабление помогают передать фразу, но не должны разрушать ровную высоту и свободу звука. Выразительность важнее максимального процента на экране.'),
        'Выбери одну строку песни. Проговори её, отметь карандашом вдох, затем спой на удобной высоте. Сравни, понятны ли слова и хватает ли спокойного выдоха до конца.',
        'Что полезно сделать перед пением новой строки?', ('Проговорить её в ритме и наметить вдох', 'Увеличить громкость до максимума', 'Убрать все согласные навсегда'), 0,
        'Речь в ритме помогает связать слова, дыхание и музыкальные ударения.'),
    Lesson('routine', '03 · Практика', 'Занятие на 10 минут и забота о голосе', 5, (
        'Пример короткого занятия: 1 минута спокойной подготовки, 2 минуты мягкой разминки, 3 минуты простых нот с паузами, 3 минуты одной фразы песни, 1 минута отдыха и заметок. Это ориентир, а не обязательная нагрузка.',
        'Запиши одно наблюдение: какой звук стал удобнее или какой фрагмент пока сложен. Следующее занятие начни с доступного материала. Увеличивай нагрузку постепенно, не сравнивай диапазон с чужим.',
        'Боль, жжение и нарастающая осиплость — повод прекратить пение, а не «продавить» голос. При сохраняющейся или повторяющейся осиплости обратись к ЛОР-врачу или фониатру. Если трудно дышать, нужна срочная медицинская помощь. При обычной усталости дай голосу отдых; воду пей по потребности, без обещаний мгновенно «смазать» складки.'),
        'Открой распевку и проведи короткое занятие с паузами. Закончи раньше, если голос устал. Оцени комфорт, ровность и понятность текста, а не только баллы.',
        'Во время упражнения появились боль и осиплость. Что делать?', ('Продолжить тише через боль', 'Прекратить пение и дать голосу отдых', 'Напрячь пресс сильнее'), 1,
        'Не продолжай через боль. Если симптомы сохраняются или повторяются, нужна очная оценка специалиста.'),
)
